import { randomUUID, randomBytes, createHash } from 'node:crypto';

/**
 * Identifier helpers.
 *
 * s9 uses UUIDs for primary keys (generated by Postgres or the app) and
 * a separate monotonic-ish id for outbox/queue bookkeeping.
 */

export function newId(): string {
  return randomUUID();
}

/**
 * A stable idempotency key for one execution.
 *
 * Derived from the workflow id, the trigger identity and the caller supplied
 * key so the same logical event always maps to the same key, which lets the
 * database reject duplicates even if the queue delivers twice.
 */
export function buildExecutionIdempotencyKey(parts: {
  workflowId: string;
  triggerType: string;
  triggerKey: string;
  version: number;
}): string {
  return createHash('sha256')
    .update([parts.workflowId, parts.triggerType, parts.triggerKey, String(parts.version)].join('\u0000'))
    .digest('hex')
    .slice(0, 40);
}

/**
 * Stable per-step idempotency key.
 *
 * Side effecting steps carry this so a provider that supports idempotency keys
 * can collapse a repeated delivery into one operation.
 */
export function buildStepIdempotencyKey(parts: {
  executionId: string;
  stepKey: string;
  attempt: number;
}): string {
  return createHash('sha256')
    .update([parts.executionId, parts.stepKey, String(parts.attempt)].join('\u0000'))
    .digest('hex')
    .slice(0, 32);
}

/** URL-safe random token, used for webhook slugs and endpoint secrets. */
export function randomToken(bytes = 32): string {
  return randomBytes(bytes).toString('base64url');
}

/** Short URL-safe slug used for the public webhook path segment. */
export function randomSlug(bytes = 9): string {
  return randomBytes(bytes).toString('base64url').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 16);
}

/** Digest used for webhook payload de-duplication. */
export function payloadDigest(payload: unknown): string {
  return createHash('sha256').update(stableStringify(payload)).digest('hex');
}

/** Deterministic JSON serialization (sorted object keys) for digests. */
export function stableStringify(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value ?? null);
  if (Array.isArray(value)) return `[${value.map((item) => stableStringify(item)).join(',')}]`;
  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`).join(',')}}`;
}
